import { getAISettings, saveAISettings, sendChatMessage, AIProvider, ChatMessage } from "../shared/ai-service";

Office.onReady((info) => {
  if (info.host === Office.HostType.Word) {
    // ---- Elements Setup ----
    const mainView = document.getElementById("main-view");
    const chatView = document.getElementById("chat-view");
    const fabChat = document.getElementById("fab-chat");
    const appBody = document.getElementById("app-body");

    // Converter UI elements
    const convertDocBtn = document.getElementById("convert-doc") as HTMLButtonElement;
    const convertSelBtn = document.getElementById("convert-sel") as HTMLButtonElement;
    const cancelMsg = document.getElementById("cancel-msg");
    const cancelLink = document.getElementById("cancel-link");

    // Chat UI elements
    const btnBack = document.getElementById("btn-back");
    const btnSettings = document.getElementById("btn-settings");
    const btnSendChat = document.getElementById("btn-send-chat") as HTMLButtonElement;
    const chatInput = document.getElementById("chat-input") as HTMLTextAreaElement;
    const chatMessages = document.getElementById("chat-messages");

    // Settings UI elements
    const settingsModal = document.getElementById("settings-modal");
    const btnCloseSettings = document.getElementById("btn-close-settings");
    const btnSaveSettings = document.getElementById("btn-save-settings");
    const providerSelect = document.getElementById("ai-provider") as HTMLSelectElement;
    const apiKeyInput = document.getElementById("ai-api-key") as HTMLInputElement;

    if (appBody) {
        appBody.style.display = "flex";
    }

    // ---- View Toggles ----
    fabChat?.addEventListener("click", () => {
        if (mainView) mainView.style.display = "none";
        if (fabChat) fabChat.style.display = "none";
        if (chatView) chatView.style.display = "flex";
    });

    btnBack?.addEventListener("click", () => {
        if (chatView) chatView.style.display = "none";
        if (mainView) mainView.style.display = "flex";
        if (fabChat) fabChat.style.display = "flex";
    });

    // ---- Settings Logic ----
    const loadSettingsToUI = () => {
        const settings = getAISettings();
        if (providerSelect) providerSelect.value = settings.provider;
        if (apiKeyInput) apiKeyInput.value = settings.apiKey;
    };

    btnSettings?.addEventListener("click", () => {
        loadSettingsToUI();
        if (settingsModal) settingsModal.style.display = "flex";
    });

    btnCloseSettings?.addEventListener("click", () => {
        if (settingsModal) settingsModal.style.display = "none";
    });

    btnSaveSettings?.addEventListener("click", () => {
        const settings = {
            provider: providerSelect.value as AIProvider,
            apiKey: apiKeyInput.value.trim()
        };
        saveAISettings(settings);
        if (settingsModal) settingsModal.style.display = "none";
    });

    // ---- Original Converter Logic ----
    const handleConversion = async (btn: HTMLButtonElement, isSelection: boolean) => {
        const originalText = btn.innerText;
        const progressSpan = document.getElementById("progress-text");
        let timeoutId: any = null;

        const state = { 
            isCancelled: false,
            onProgress: (remaining: number, total: number) => {
                if (cancelMsg && progressSpan) {
                    if (total > 0 && remaining > 0) {
                        btn.innerText = `Converting, ${remaining} left...`;
                        progressSpan.innerText = `So long? `;
                    } else if (remaining === 0) {
                        cancelMsg.style.display = "none";
                        btn.innerText = "Finishing...";
                    }
                }
            }
        };

        try {
            btn.disabled = true;
            btn.innerText = "Converting...";

            if (cancelMsg && cancelLink) {
                timeoutId = setTimeout(() => {
                    if (!state.isCancelled && btn.innerText.includes("Converting")) {
                        cancelMsg.style.display = "block";
                    }
                }, 5000);

                cancelLink.onclick = (e) => {
                    e.preventDefault();
                    state.isCancelled = true;
                    btn.innerText = "Cancelling...";
                    cancelMsg.style.display = "none";
                };
            }

            const { runConversion } = await import("../shared/converter");
            await runConversion(isSelection, state);
        } finally {
            if (timeoutId) clearTimeout(timeoutId);
            if (cancelMsg) cancelMsg.style.display = "none";
            btn.disabled = false;
            btn.innerText = originalText;
        }
    };

    if (convertDocBtn) {
        convertDocBtn.onclick = () => handleConversion(convertDocBtn, false);
    }
    if (convertSelBtn) {
        convertSelBtn.onclick = () => handleConversion(convertSelBtn, true);
    }

    // ---- Chat AI Logic ----
    let chatHistory: ChatMessage[] = [];

    const appendUserMessage = (text: string) => {
        if (!chatMessages) return;
        const div = document.createElement("div");
        div.className = "chat-msg user-msg";
        div.innerHTML = `<div class="msg-bubble">${escapeHtml(text)}</div>`;
        chatMessages.appendChild(div);
        scrollToBottom();
    };

    const appendAIMessage = (textPart: string, latexPart: string | null, mathMLHtml: string | null) => {
        if (!chatMessages) return;
        const div = document.createElement("div");
        div.className = "chat-msg ai-msg";
        
        let html = '<div class="msg-bubble">';
        if (textPart && textPart.trim() !== "") {
            html += `<div style="margin-bottom: ${mathMLHtml ? '12px' : '0'};">${escapeHtml(textPart).replace(/\n/g, '<br>')}</div>`;
        }
        if (mathMLHtml) {
            html += `<div style="font-size: 12px; color: var(--color-text-muted); margin-bottom: 4px;">Created Formula:</div>`;
            html += mathMLHtml;
        }
        html += '</div>';
        
        div.innerHTML = html;
        chatMessages.appendChild(div);
        scrollToBottom();
    };

    const appendAIError = (errorStr: string) => {
        if (!chatMessages) return;
        const div = document.createElement("div");
        div.className = "chat-msg ai-msg";
        div.innerHTML = `<div class="msg-bubble" style="color: #d83b01;">Error: ${escapeHtml(errorStr)}</div>`;
        chatMessages.appendChild(div);
        scrollToBottom();
    };

    let skeletonEl: HTMLElement | null = null;
    const showSkeleton = () => {
        if (!chatMessages) return;
        skeletonEl = document.createElement("div");
        skeletonEl.className = "chat-msg ai-msg";
        skeletonEl.innerHTML = `
            <div class="skeleton-loader">
                <div class="skeleton-line"></div>
                <div class="skeleton-line"></div>
                <div class="skeleton-line"></div>
            </div>`;
        chatMessages.appendChild(skeletonEl);
        scrollToBottom();
    };

    const removeSkeleton = () => {
        if (skeletonEl && skeletonEl.parentNode) {
            skeletonEl.parentNode.removeChild(skeletonEl);
        }
        skeletonEl = null;
    };

    const scrollToBottom = () => {
        if (chatMessages) {
            chatMessages.scrollTop = chatMessages.scrollHeight;
        }
    };

    const escapeHtml = (unsafe: string) => {
        return unsafe.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    };

    const handleSendChat = async () => {
        const prompt = chatInput?.value.trim();
        if (!prompt) return;

        chatInput.value = "";
        btnSendChat.disabled = true;

        appendUserMessage(prompt);
        showSkeleton();

        try {
            let selectedText = "";
            // Get currently selected text to provide context
            await Word.run(async (context) => {
                const selection = context.document.getSelection();
                selection.load("text");
                await context.sync();
                selectedText = selection.text;
            });

            // Add user message to history
            chatHistory.push({ role: "user", content: prompt });

            // Call AI with full history
            const aiResponseText = await sendChatMessage(chatHistory, selectedText);
            removeSkeleton();

            // Add AI response to history
            chatHistory.push({ role: "assistant", content: aiResponseText });

            // Parse response for <formula> tags
            const formulaRegex = /<formula>([\s\S]*?)<\/formula>/g;
            let match;
            let lastIndex = 0;
            let textParts = [];
            let formulas = [];
            
            while ((match = formulaRegex.exec(aiResponseText)) !== null) {
                textParts.push(aiResponseText.substring(lastIndex, match.index));
                formulas.push(match[1]);
                lastIndex = formulaRegex.lastIndex;
            }
            textParts.push(aiResponseText.substring(lastIndex));

            const normalText = textParts.join("").trim();

            if (formulas.length === 0) {
                appendAIMessage(normalText, null, null);
            } else {
                const { sanitizeLaTeX, getMathML } = await import("../shared/converter");
                for (let i = 0; i < formulas.length; i++) {
                    let rawLatex = formulas[i].trim();
                    // Optional cleaning
                    if (rawLatex.startsWith("$$") && rawLatex.endsWith("$$")) {
                        rawLatex = rawLatex.substring(2, rawLatex.length - 2).trim();
                    }

                    const isBlock = rawLatex.includes("$$") || rawLatex.includes("\\begin{");
                    const latexClean = sanitizeLaTeX(rawLatex, isBlock);
                    const mathML = getMathML(latexClean, isBlock);

                    if (mathML) {
                        appendAIMessage(i === 0 ? normalText : "", latexClean, mathML);
                        // Insert into Word Document replacing selection
                        await Word.run(async (context) => {
                            const selection = context.document.getSelection();
                            const wrappedMathML = `<html><body>${mathML}</body></html>`;
                            selection.insertHtml(wrappedMathML, Word.InsertLocation.replace);
                            await context.sync();
                        });
                    } else {
                        appendAIError("Failed to render LaTeX formula.");
                    }
                }
            }

        } catch (e: any) {
            removeSkeleton();
            chatHistory.pop(); // remove user message if failed
            appendAIError(e.message || "Unknown error");
        } finally {
            btnSendChat.disabled = false;
        }
    };

    btnSendChat?.addEventListener("click", handleSendChat);
    chatInput?.addEventListener("keydown", (e) => {
        if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault();
            handleSendChat();
        }
    });

  }
});
