export type AIProvider = 'openai' | 'gemini' | 'deepseek';

export interface AISettings {
    provider: AIProvider;
    apiKey: string;
}

const SETTINGS_KEY = 'auto_latex_ai_settings';

export function getAISettings(): AISettings {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) {
        try {
            return JSON.parse(raw);
        } catch (e) {
            console.error("Failed to parse AI Settings", e);
        }
    }
    return { provider: 'gemini', apiKey: '' };
}

export function saveAISettings(settings: AISettings) {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
}

const SYSTEM_PROMPT = `Bạn là trợ lý AI tên là Auto-LaTeX Copilot, hỗ trợ người dùng soạn thảo và chỉnh sửa công thức toán học LaTeX trong Microsoft Word.
Bạn có thể trò chuyện bình thường và giải đáp thắc mắc của người dùng.

KHI NGƯỜI DÙNG YÊU CẦU TẠO HOẶC CHỈNH SỬA CÔNG THỨC TOÁN HỌC:
1. Bạn phải xuất công thức toán học bằng ngôn ngữ LaTeX.
2. Bạn BẮT BUỘC phải bọc toàn bộ mã LaTeX của công thức đó bên trong cặp thẻ <formula> và </formula>. 
Ví dụ: <formula>x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}</formula>
3. KHÔNG sử dụng ký hiệu đô la ($ hoặc $$) bên trong thẻ <formula> trừ khi thật sự cần thiết.
4. Mọi văn bản giải thích có thể để ở ngoài thẻ <formula>.
Hệ thống sẽ tự động tìm thẻ <formula> và chèn vào văn bản của người dùng.`;

export interface ChatMessage {
    role: "user" | "assistant";
    content: string;
}

export async function sendChatMessage(history: ChatMessage[], contextText: string = ""): Promise<string> {
    const settings = getAISettings();
    if (!settings.apiKey) {
        throw new Error("Missing API Key. Please open Settings to set your API Key.");
    }

    // Clone history to avoid modifying original array
    const messagesToSend = [...history];

    // If contextText exists, append it to the LAST user message
    if (contextText && contextText.trim() !== "") {
        const lastUserMsgIndex = messagesToSend.findLastIndex(m => m.role === "user");
        if (lastUserMsgIndex >= 0) {
            messagesToSend[lastUserMsgIndex] = {
                ...messagesToSend[lastUserMsgIndex],
                content: `${messagesToSend[lastUserMsgIndex].content}\n\n[Bối cảnh văn bản đang bôi đen]:\n${contextText}`
            };
        }
    }

    if (settings.provider === 'openai') {
        return callOpenAICompatible(messagesToSend, settings.apiKey, "https://api.openai.com/v1/chat/completions", "gpt-4o-mini");
    } else if (settings.provider === 'deepseek') {
        return callOpenAICompatible(messagesToSend, settings.apiKey, "https://api.deepseek.com/chat/completions", "deepseek-reasoner", {
            thinking: { type: "enabled" },
            reasoning_effort: "high"
        });
    } else {
        return callGemini(messagesToSend, settings.apiKey);
    }
}

async function callOpenAICompatible(history: ChatMessage[], apiKey: string, endpoint: string, model: string, extraBodyParams: any = {}): Promise<string> {
    const apiMessages = [
        { role: "system", content: SYSTEM_PROMPT },
        ...history
    ];

    const body: any = {
        model: model,
        messages: apiMessages,
        temperature: 0.2,
        ...extraBodyParams
    };
    
    // Deepseek thinking mode does not support temperature, so we remove it if thinking is enabled
    if (extraBodyParams.thinking && extraBodyParams.thinking.type === "enabled") {
        delete body.temperature;
    }

    const response = await fetch(endpoint, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${apiKey}`
        },
        body: JSON.stringify(body)
    });

    if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error?.message || "OpenAI API Error");
    }

    const data = await response.json();
    let content = data.choices[0]?.message?.content || "";
    return content.trim();
}

async function callGemini(history: ChatMessage[], apiKey: string): Promise<string> {
    // Using Gemini 1.5 Flash for speed
    const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${apiKey}`;
    
    // Convert history format to Gemini format (user/model)
    const geminiContents = history.map(msg => ({
        role: msg.role === "assistant" ? "model" : "user",
        parts: [{ text: msg.content }]
    }));

    const response = await fetch(url, {
        method: "POST",
        headers: {
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            system_instruction: {
                parts: [{ text: SYSTEM_PROMPT }]
            },
            contents: geminiContents,
            generationConfig: {
                temperature: 0.2
            }
        })
    });

    if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error?.message || "Gemini API Error");
    }

    const data = await response.json();
    let content = data.candidates?.[0]?.content?.parts?.[0]?.text || "";
    return content.trim();
}
